content.text:
        counts[name] = counts.get(name, 0) + 1

    for name in counts:
        if name in PROHIBITED_NAMES:
            return None

    te_values = [value for name, value in regular if name == b"te"]
    if len(te_values) > 1:
        return None
    if te_values and te_values[0] != b"trailers":
        return None

    content_lengths = [value for name, value in regular if name == b"content-length"]
    if content_lengths and not parse_content_length(content_lengths, len(body)):
        return None

    for name, count in counts.items():
        if name in (b"host", b"te", b"content-length", b"cookie"):
            continue
        if count > 1:
            if name in REPEATABLE_NAMES or is_list_name(name):
                continue
            return None

    # Trailers.
    trailers = None
    if trailer_pairs is not None:
        trailers = []
        for name, value in trailer_pairs:
            if not valid_field_value(value):
                return None
            if not valid_regular_name(name):
                return None
            if not name.startswith(TRAILER_PREFIX) or len(name) <= len(TRAILER_PREFIX):
                return None
            trailers.append((name, value))

    # Route lookup.
    route_key = scheme.decode("ascii") + "://" + authority_bytes.decode("ascii")
    origin = routes.get(route_key)
    if origin is None:
        return None

    # Emitted regular fields: occurrence order, host/content-length/te removed,
    # cookie lines merged into one line at the first cookie position.
    cookie_values = [value for name, value in regular if name == b"cookie"]
    joined_cookie = b"; ".join(cookie_values) if cookie_values else None
    emitted = []
    cookie_done = False
    for name, value in regular:
        if name in (b"host", b"content-length", b"te"):
            continue
        if name == b"cookie":
            if cookie_done:
                continue
            cookie_done = True
            emitted.append((name, joined_cookie))
            continue
        emitted.append((name, value))

    raw = bytearray()
    raw += method + b" " + path + b" HTTP/1.1\r\n"
    raw += b"host: " + authority_bytes + b"\r\n"
    for name, value in emitted:
        raw += name + b": " + value + b"\r\n"
    if trailer_pairs is None:
        raw += b"content-length: " + str(len(body)).encode("ascii") + b"\r\n"
        raw += b"\r\n"
        raw += body
    else:
        raw += b"transfer-encoding: chunked\r\n"
        if trailers:
            names = []
            for name, _ in trailers:
                if name not in names:
                    names.append(name)
            raw += b"trailer: " + b", ".join(names) + b"\r\n"
        raw += b"\r\n"
        if body:
            raw += format(len(body), "x").encode("ascii") + b"\r\n"
            raw += body
            raw += b"\r\n"
        raw += b"0\r\n"
        for name, value in trailers:
            raw += name + b": " + value + b"\r\n"
        raw += b"\r\n"

    return {
        "origin": origin,
        "raw": bytes(raw),
        "cache_key": [
            method.decode("ascii"),
            scheme.decode("ascii"),
            authority_bytes.decode("ascii"),
            path.decode("ascii"),
        ],
    }


def blank_record(sid, status):
    return {
        "sid": sid,
        "status": status,
        "commit_at": None,
        "origin": None,
        "offset": None,
        "length": 0,
        "cache_key": None,
    }


def bridge(scenario):
    routes = scenario.get("routes") or {}
    events = scenario.get("events") or []

    pipelines = {}
    for label in routes.values():
        pipelines.setdefault(label, bytearray())

    states = {}
    records = {}

    for index, event in enumerate(events):
        sid = event["sid"]
        state = states.get(sid)
        if state is None:
            state = states[sid] = {
                "kinds": [],
                "sections": [],
                "body": bytearray(),
                "terminal": None,
            }
        kind = event.get("type")
        if kind == "headers":
            state["kinds"].append("headers")
            state["sections"].append(parse_section(event.get("fields") or []))
        elif kind == "data":
            state["kinds"].append("data")
            try:
                state["body"].extend(bytes.fromhex(event.get("hex") or ""))
            except ValueError:
                state["broken"] = True
        elif kind == "unknown":
            pass
        elif kind == "fin":
            state["terminal"] = ("fin", index)
        elif kind == "reset":
            state["terminal"] = ("reset", index)

    for sid in sorted(states):
        state = states[sid]
        terminal = state["terminal"]
        if terminal is None:
            records[sid] = blank_record(sid, "incomplete")
            continue
        kind, index = terminal
        if kind == "reset":
            records[sid] = blank_record(sid, "cancelled")
            continue
        request = evaluate(state, routes)
        if request is None:
            records[sid] = blank_record(sid, "rejected")
            continue
        origin = request["origin"]
        pipeline = pipelines.setdefault(origin, bytearray())
        offset = len(pipeline)
        raw = request["raw"]
        pipeline.extend(raw)
        records[sid] = {
            "sid": sid,
            "status": "forwarded",
            "commit_at": index,
            "origin": origin,
            "offset": offset,
            "length": len(raw),
            "cache_key": request["cache_key"],
        }

    return {
        "streams": [records[sid] for sid in sorted(records)],
        "origins": {label: bytes(raw).hex() for label, raw in pipelines.items()},
    }


def main():
    data = sys.stdin.buffer.read()
    scenario = json.loads(data.decode("utf-8"))
    result = bridge(scenario)
    out = json.dumps(result, ensure_ascii=True)
    sys.stdout.write(out)
    sys.stdout.write("\n")
